        String digits = raw.replaceAll("\\D", "");
        if (!raw.startsWith("+")) {
            digits = "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
        }
        if (digits.length() < 8 || digits.length() > 15) {
            throw new MissingFieldsException(List.of("telephone"));
        }
        request.setTelephone("+" + digits);
    }
}

